describe('Mobile Hamburger Menu Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should open hamburger menu when clicking the menu button', () => {
    cy.get('[data-testid="hamburger-menu-button"]').should('be.visible');
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');
    cy.get('[data-testid="mobile-menu"]').should('have.class', 'open');
  });

  it('should close hamburger menu when clicking the menu button again', () => {
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('not.have.class', 'open');
  });

  it('should close menu when clicking on a menu item', () => {
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');
    cy.get('[data-testid="mobile-menu-item"]').first().click();
    cy.get('[data-testid="mobile-menu"]').should('not.have.class', 'open');
  });

  it('should close menu when clicking outside the menu', () => {
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');
    cy.get('body').click(0, 0);
    cy.get('[data-testid="mobile-menu"]').should('not.have.class', 'open');
  });

  it('should toggle menu state multiple times without errors', () => {
    for (let i = 0; i < 3; i++) {
      cy.get('[data-testid="hamburger-menu-button"]').click();
      cy.get('[data-testid="mobile-menu"]').should('have.class', 'open');
      cy.get('[data-testid="hamburger-menu-button"]').click();
      cy.get('[data-testid="mobile-menu"]').should('not.have.class', 'open');
    }
  });

  it('should display all menu items when menu is open', () => {
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');
    cy.get('[data-testid="mobile-menu-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="mobile-menu-item"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });
  });

  it('should hide menu items when menu is closed', () => {
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('not.be.visible');
  });

  it('should maintain menu state during page interactions', () => {
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('have.class', 'open');
    cy.get('[data-testid="page-content"]').click();
    cy.get('[data-testid="mobile-menu"]').should('not.have.class', 'open');
  });
});
